//@ts-check
import { getRequire, isNodejsRuntime } from '../../utils/Runtime.js'

const requireDynamic = getRequire(import.meta.url)

/** @typedef {import('ws').WebSocket} wsClient */
/** @typedef {typeof import('ws').WebSocket} WebSocketClass */

/**
 * Enum for WebSocket states.
 * @readonly
 * @enum {number}
 */
const WebSocketStateEnum = {
    CONNECTING: 0,
    OPEN: 1,
    CLOSING: 2,
    CLOSED: 3,
}

/**
 * Enum for WebSocket event states.
 * @readonly
 * @enum {string}
 */
const WebSocketStateEvent = {
    OPEN: 'open',
    CLOSE: 'close',
    ERROR: 'error',
    MESSAGE: 'message',
}

/** @type {WebSocketClass | null} */
let WebSocket = null

/** @type {Record<string, wsClient>} */
export const clients = {}

/** @type {Record<string, Array<{resolve: Function, reject: Function, messageArray: Uint8Array}>>} */
export const messageQueue = {}

/** @type {Record<string, boolean>} */
export const processingQueues = {}

const MAX_ATTEMPTS = 2
const DEFAULT_CONNECT_TIMEOUT_SECONDS = 3
const DEFAULT_CONNECT_TIMEOUT_MS = DEFAULT_CONNECT_TIMEOUT_SECONDS * 1000
const DEFAULT_RESPONSE_TIMEOUT_SECONDS = 180
const DEFAULT_RESPONSE_TIMEOUT_MS = DEFAULT_RESPONSE_TIMEOUT_SECONDS * 1000

/**
 * @typedef {import('../../utils/connectionData/WsConnectionData.js').WsConnectionData} WsConnectionData
 */

/**
 * @param {WsConnectionData} wsConnectionData
 * @returns {void}
 */
export function resetConnectionState(wsConnectionData) {
    const cacheKey = wsConnectionData.toCanonicalKey()
    const client = clients[cacheKey]
    if (client) {
        try {
            client.close()
        } catch {
            /* ignore */
        }
        delete clients[cacheKey]
    }

    if (messageQueue[cacheKey]) {
        messageQueue[cacheKey].forEach(({ reject }) => {
            reject(
                new Error(
                    'WebSocket connection was reset. The connection was closed before the operation completed.'
                )
            )
        })
        delete messageQueue[cacheKey]
    }

    delete processingQueues[cacheKey]
}

/**
 * WebSocketClient class that handles WebSocket connection, message sending, and automatic disconnection.
 */
class WebSocketClient {
    /**
     * @param {WsConnectionData} wsConnectionData
     * @param {{ isDisconnectedAfterMessage?: boolean }} options
     */
    constructor(wsConnectionData, options) {
        this.connectionData = wsConnectionData
        /** @type {string} */
        this.url = wsConnectionData.hostname
        const parsedUrl = new URL(this.url)
        if (parsedUrl.protocol !== 'ws:' && parsedUrl.protocol !== 'wss:') {
            throw new Error(
                `WebSocketClient requires 'ws' (WebSocket) or 'wss' (WebSocket over TLS) scheme. Provided URL: ${this.url}`
            )
        }
        /** @type {boolean} */
        this.isDisconnectedAfterMessage = options?.isDisconnectedAfterMessage ?? false
        this.requestHeaders = this._buildRequestHeadersFromConnectionData()
    }

    get cacheKey() {
        return this.connectionData.toCanonicalKey()
    }

    /** @type {wsClient | null} */
    get instance() {
        return clients[this.cacheKey] || null
    }

    get isConnected() {
        return this.instance ? this.instance?.readyState === WebSocketStateEnum.OPEN : false
    }

    /**
     * Sends messageArray through websocket connection with guaranteed order preservation
     * @async
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    send(messageArray) {
        if (messageArray == null) {
            return Promise.reject(new Error('messageArray must not be null or undefined'))
        }

        return new Promise((resolve, reject) => {
            if (!messageQueue[this.cacheKey]) {
                messageQueue[this.cacheKey] = []
            }
            messageQueue[this.cacheKey].push({ resolve, reject, messageArray })

            this._processMessage()
        })
    }

    /**
     * Processes message queue sequentially to maintain order
     * @private
     * @async
     */
    async _processMessage() {
        if (processingQueues[this.cacheKey]) {
            return
        }
        processingQueues[this.cacheKey] = true

        try {
            while (messageQueue[this.cacheKey] && messageQueue[this.cacheKey].length > 0) {
                const item = messageQueue[this.cacheKey].shift()
                if (!item) break

                const { resolve, reject, messageArray } = item

                try {
                    const response = await this._sendWithRetry(messageArray)
                    resolve(response)
                } catch (error) {
                    reject(error)
                }
            }
        } finally {
            processingQueues[this.cacheKey] = false
        }
    }

    /**
     * Sends a message with NetCore-style maxAttempts retry semantics.
     * @private
     * @async
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    async _sendWithRetry(messageArray) {
        let lastError = null

        for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            try {
                return await this._send(messageArray)
            } catch (error) {
                lastError = error
                if (!isTransientWebSocketError(error)) {
                    // Evict desynced/broken connection after final failure (bug 32346).
                    this._closeCachedClientForRetry()
                    throw error
                }
                if (attempt === MAX_ATTEMPTS - 1) {
                    break
                }
                this._closeCachedClientForRetry()
            }
        }

        // Evict desynced/broken connection after final failure (bug 32346).
        this._closeCachedClientForRetry()
        throw new Error(
            `WebSocket send to ${this.url} failed after ${MAX_ATTEMPTS} attempts. Last error: ${getErrorMessage(lastError)}`
        )
    }

    /**
     * Sends a single message through websocket connection
     * @private
     * @async
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    _send(messageArray) {
        return new Promise((resolve, reject) => {
            const sendAndWaitForResponse = (/** @type {wsClient} */ client) => {
                client.send(/** @type {any} */ (messageArray))
                const responseTimeoutInSeconds =
                    this.connectionData.responseTimeoutInSeconds ?? DEFAULT_RESPONSE_TIMEOUT_SECONDS

                /** @type {ReturnType<typeof setTimeout>} */
                let receiveTimeout
                let settled = false

                const cleanup = () => {
                    clearTimeout(receiveTimeout)
                    client.removeListener(WebSocketStateEvent.MESSAGE, messageHandler)
                    client.removeListener(WebSocketStateEvent.CLOSE, closeHandler)
                    client.removeListener(WebSocketStateEvent.ERROR, errorHandler)
                }

                const fail = (/** @type {Error} */ error) => {
                    if (settled) {
                        return
                    }
                    settled = true
                    cleanup()
                    reject(error)
                }

                const messageHandler = (/** @type {any} */ message) => {
                    if (settled) {
                        return
                    }
                    settled = true
                    cleanup()
                    resolve(message)
                    if (this.isDisconnectedAfterMessage) {
                        this.disconnect()
                    }
                }

                const closeHandler = () => {
                    fail(
                        new Error(
                            `WebSocket connection to ${this.url} was closed by the remote endpoint while waiting for response. ` +
                                'The server may have shut down or closed the connection.'
                        )
                    )
                }

                const errorHandler = (/** @type {unknown} */ error) => {
                    fail(
                        new Error(
                            `WebSocket receive from ${this.url} failed while waiting for response: ${getErrorMessage(error)}`
                        )
                    )
                }

                if (responseTimeoutInSeconds >= 0) {
                    const responseTimeoutMs =
                        responseTimeoutInSeconds === DEFAULT_RESPONSE_TIMEOUT_SECONDS
                            ? DEFAULT_RESPONSE_TIMEOUT_MS
                            : responseTimeoutInSeconds * 1000
                    receiveTimeout = setTimeout(() => {
                        fail(
                            new Error(
                                `WebSocket receive from ${this.url} timed out after ${responseTimeoutInSeconds} seconds.`
                            )
                        )
                    }, responseTimeoutMs)
                }

                client.on(WebSocketStateEvent.MESSAGE, messageHandler)
                client.on(WebSocketStateEvent.CLOSE, closeHandler)
                client.on(WebSocketStateEvent.ERROR, errorHandler)
            }

            const client = this.instance
            if (client && this.isConnected) {
                sendAndWaitForResponse(client)
            } else {
                this._connect().then(sendAndWaitForResponse).catch(reject)
            }
        })
    }

    /**
     * Disconnects the WebSocket by terminating the connection and cleans up queues.
     */
    disconnect() {
        resetConnectionState(this.connectionData)
    }

    /**
     * @private
     */
    _closeCachedClientForRetry() {
        const client = this.instance
        if (!client) {
            return
        }
        try {
            client.close()
        } catch {
            /* ignore */
        }
        delete clients[this.cacheKey]
    }

    /**
     * Connects to the WebSocket server.
     * @private
     * @async
     * @returns {Promise<wsClient>} - A promise that resolves when the connection is established.
     */
    _connect() {
        if (!WebSocket && isNodejsRuntime()) {
            try {
                WebSocket = requireDynamic('ws')
            } catch (error) {
                if (/** @type {{ code?: string }} */ (error).code === 'MODULE_NOT_FOUND') {
                    throw new Error(
                        'WebSocket connection failed: the "ws" package is not installed. ' +
                            'Install it with: npm install ws'
                    )
                }
                throw error
            }
        }

        return new Promise((resolve, reject) => {
            if (!WebSocket) {
                return reject(
                    new Error(
                        'WebSocket connection failed: ws client is not available. ' +
                            'In Node.js ensure the "ws" package is installed (npm install ws).'
                    )
                )
            }

            let client = clients[this.cacheKey]
            if (client && client.readyState === WebSocketStateEnum.OPEN) {
                return resolve(client)
            }

            if (client && client.readyState !== WebSocketStateEnum.CLOSED) {
                this._attachConnectHandlers(client, resolve, reject)
                return
            }

            client = new WebSocket(this.url, {
                headers: this._buildRequestHeaders(),
                handshakeTimeout: DEFAULT_CONNECT_TIMEOUT_MS,
            })
            clients[this.cacheKey] = client
            this._attachConnectHandlers(client, resolve, reject)
        })
    }

    /**
     * @private
     * @param {wsClient} client
     * @param {(client: wsClient) => void} resolve
     * @param {(error: Error) => void} reject
     */
    _attachConnectHandlers(client, resolve, reject) {
        const wrapReject = (/** @type {Error | unknown} */ err) => {
            const msg = err instanceof Error ? err.message : String(err)
            const wrapped = new Error(
                `WebSocket connection to ${this.url} failed: ${msg}. ` +
                    'Check that the server is running, the URL is correct (ws:// or wss://), ' +
                    'and that no firewall or proxy is blocking the connection.'
            )
            if (err instanceof Error && 'cause' in Error.prototype) {
                const errorWithCause = /** @type {Error & { cause?: unknown }} */ (wrapped)
                errorWithCause.cause = err
            }
            reject(wrapped)
        }

        client.once(WebSocketStateEvent.OPEN, () => resolve(client))
        client.once(WebSocketStateEvent.ERROR, (/** @type {unknown} */ error) => wrapReject(error))
        client.once(WebSocketStateEvent.CLOSE, () => {
            reject(
                new Error(
                    `WebSocket connection to ${this.url} was closed before it could be established. ` +
                        'The server may have refused the connection, closed immediately, or a network error occurred. ' +
                        'Check that the server is running and the URL is correct.'
                )
            )
        })
    }

    /**
     * @private
     * @returns {Record<string, string | string[]>}
     */
    _buildRequestHeaders() {
        return this.requestHeaders
    }

    /**
     * @private
     * @returns {Record<string, string | string[]>}
     */
    _buildRequestHeadersFromConnectionData() {
        /** @type {Record<string, string | string[]>} */
        const requestHeaders = {}

        for (const [key, value] of Object.entries(this.connectionData.getHeaders())) {
            if (!key || value == null) {
                continue
            }
            if (isRestrictedWebSocketHeader(key)) {
                console.warn(`WebSocket header '${key}' is reserved and was ignored.`)
                continue
            }
            requestHeaders[key] = value
        }

        return requestHeaders
    }
}

/**
 * @param {unknown} error
 * @returns {boolean}
 */
function isTransientWebSocketError(error) {
    if (!(error instanceof Error)) {
        return true
    }
    return !/messageArray must not be null or undefined/.test(error.message)
}

/**
 * @param {unknown} error
 * @returns {string}
 */
function getErrorMessage(error) {
    return error instanceof Error ? error.message : String(error)
}

/**
 * @param {string} key
 * @returns {boolean}
 */
function isRestrictedWebSocketHeader(key) {
    const normalized = key.toLowerCase()
    return ['host', 'upgrade', 'connection'].includes(normalized) || normalized.startsWith('sec-websocket-')
}

export { DEFAULT_RESPONSE_TIMEOUT_SECONDS, WebSocketClient }
